    "/host/vms": [
      {
        "id": "MCL-0bf59b7057f2d62a",
        "text": "Vast can run KVM virtual machines in addition to Docker containers. VM support is optional and depends heavily on hardware, BIOS, kernel, and GPU configuration.",
        "headings": [
          "Introduction"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 13,
            "end": 13,
            "text_sha256": "1e71824b42534f7f714eb8557fbae350584b733c249a5d9a85f33c3048309e5c"
          }
        ],
        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "e282f2950cd8f7a806b581ba8928a556703d96afee84f7b9a2145c20cb8eaf31"
      },
      {
        "id": "MCL-9ca15e77224c7a3d",
        "text": "VMs interact more directly with hardware than containers. Enable them only when the machine supports IOMMU and remains stable.",
        "headings": [
          "Introduction"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 16,
            "end": 16,
            "text_sha256": "3aede8791ee92567968b1a6292f342aa439c7dd679f3db039898c69c4032e1fb"
          }
        ],
        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "3a037afe38ca2e9e8fb8df41918d46bbc27538fff32cb829d5b2b4f994bf4292"
      },
      {
        "id": "MCL-09862d593c097a0d",
        "text": "Default host onboarding should still start from the official [Vast host setup page](https://cloud.vast.ai/host/setup/). Use this page only for optional VM/IOMMU planning or troubleshooting after the normal host setup path is understood.",
        "headings": [
          "Introduction"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 19,
            "end": 19,
            "text_sha256": "c485dfadf9d75edc2d36d4351bb00f03a09d6226964c51b64d93e401445e072c"
          }
        ],
        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "3cdbe96573869d5799e596a4df986822fa7e3d07c2444ed542e50254d475eeeb"
      },
      {
        "id": "MCL-6298e849542e75e0",
        "text": "VM support can make a host visible to renters using VM templates and can help with workloads that need:",
        "headings": [
          "When VM Support Helps"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 23,
            "end": 23,
            "text_sha256": "c4347ad8dfd091a433d4de22da0e16d38a76b489fe96cf8e3da1978afc7c41a3"
          }
        ],
        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "5f05cd8dbbbdcf93d1b122f2141e38ba1f492af1ee1cc033701fadbdf4bbdb37"
      },
      {
        "id": "MCL-ca5f66dfd10f2d88",
        "text": "- Systemd, Docker Compose, Kubernetes, or Docker build workflows.",
        "headings": [
          "When VM Support Helps"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 25,
            "end": 25,
            "text_sha256": "31f5d963ea810d41971895a0f506f395e24913e64b92b207625ae36edcbb768d"
          }
        ],
        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "3a32aa63d475971810229a54402d487c9eafdd5cd5edcd1c60aa7727930e84a1"
      },
      {
        "id": "MCL-629c125e1f628486",
        "text": "- Non-Linux OS images.",
        "headings": [
          "When VM Support Helps"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 26,
            "end": 26,
            "text_sha256": "d2f7eb9745798ca119997cc0f179fa625681f5d5fb55482b2fddc7bc1461bcb1"
          }
        ],
        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "a5b99c05acc87b19bbb38e9e5eb50c47b103a8e7866dca604d1a5bff4bd216c8"
      },
      {
        "id": "MCL-539e53da13d21fa0",
        "text": "- `ptrace` tooling such as NVIDIA Nsight.",
        "headings": [
          "When VM Support Helps"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 27,
            "end": 27,
