        "historical_claim_sha256": "76e7e05d608b753a678f4ecb34d797e4e2979cf56f379522cb063737df0a878e"
      },
      {
        "id": "MCL-6b11a6264600fa57",
        "text": "Single-GPU hosts usually have the lowest VM risk. Multi-GPU RTX 40-series hosts may also benefit. Multi-GPU datacenter hosts should be more cautious until VM P2P/NVLink behavior is a good fit for the workload.",
        "headings": [
          "When VM Support Helps"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 29,
            "end": 29,
            "text_sha256": "9a42bbd340973da334841543d54bd3b3fab12645b88d72999668c23de30cba2c"
          }
        ],
        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "dcfc0543ad9089c3a069f28b273f42e298fe6088d720f1385955ff8d717ebd72"
      },
      {
        "id": "MCL-6cb4c04ce10a0fe3",
        "text": "- IOMMU settings can reduce PCIe peer-to-peer performance on some multi-GPU systems.",
        "headings": [
          "Tradeoffs"
