        "historical_claim_sha256": "721ca83b91567e249f6cbca1e8b44c937a6df74098908d7efc9f754b7e3ea773"
      },
      {
        "id": "MCL-efe998f80897bbe8",
        "text": "- VMs can use more disk than containers.",
        "headings": [
          "Tradeoffs"
