      {
        "id": "MCL-442f5fb5941fefd1",
        "text": "Disabling VM support changes Host configuration and can disrupt running work. Prevent new rentals during the approved maintenance window, then confirm the machine has no active rentals or other workloads.",
        "headings": [
          "Disable VM Support"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
