        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "d304ed4a98876f66fbbcb30b48c9531cd5ac62f134b9b4c42d85b209bcb7e23b"
      },
      {
        "id": "MCL-256a7246625a0529",
        "text": "This is a forced, state-changing setup retry—not a simple toggle. It can install VM packages, pull a test image, restart Host services, and run a GPU-passthrough test. Prevent new rentals during the approved maintenance window, then confirm there are no active rentals, containers, or GPU workloads.",
        "headings": [
          "Retry Enablement"
        ],
        "spans": [
          {
            "source_file": "host/vms.mdx",
            "start": 105,
            "end": 105,
            "text_sha256": "2f22ad303d55c3faa3bef9f7dd7f6dc5eb1a283899bdbdda64a7659db3d595fc"
