        "historical_status": "UNVALIDATED",
        "historical_claim_sha256": "48e33a4911723f06e6802b3c720106771cb129a0d075ae2e90ca3b6a485dae98"
      },
      {
        "id": "MCL-eb4fa2c8374b1359",
        "text": "- Hosts with VM support may need higher disk and bandwidth prices.",
        "headings": [
          "Tradeoffs"
